// Token Weather: a live forecast of the context window, above the prompt.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionContextUsage, SessionRateLimit, Timer } from 'claude-code'

import type { TokenWeatherLimit, TokenWeatherReading } from '../types'
import { DAY, WEEK_HEIGHT, WEEK_WIDTH, dial, elapsed, glyph, trend, trendWidth, week } from './sky'

// Readings kept: one more than the bars, which are the gains between them.
const HISTORY = 7
const BARS = '▁▂▃▄▅▆▇█'
// `color` is the theme's name for the text; `hex` the same hue in the band's drawings.
const FORECAST = [
  { upTo: 25, icon: '☀', sky: 'sun', word: 'Clear', color: 'yellow', hex: '#f6d909' },
  { upTo: 50, icon: '☁', sky: 'cloud', word: 'Cloudy', color: 'cyan', hex: '#08a2c3' },
  { upTo: 75, icon: '☂', sky: 'rain', word: 'Showers', color: 'blue', hex: '#5b8def' },
  { upTo: 90, icon: '☇', sky: 'storm', word: 'Storm', color: 'magenta', hex: '#b77ce0' },
  { upTo: Infinity, icon: '↯', sky: 'funnel', word: 'Compact soon', color: 'red', hex: '#e5484d' },
] as const
const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const ORANGE = '#f0883e'
// The plan's rate-limit windows to show, in order, with their labels.
const LIMIT_LABELS: Record<string, string> = { five_hour: '5h', seven_day: '7d' }
// Windows whose reset countdown is drawn after the percentage.
const SHOW_RESET = new Set(['five_hour'])
// How often the band redraws so the countdown keeps time between turns.
const TICK_MS = 30_000
// Width of one text cell on the desktop, to fit the band to `bodyColumns`.
const CELL_PX = 8

// The band is one line of groups; one that does not fit leaves a dot in its color.
const GAP = '  '
const DOT = '•'
// A terminal group is a run of spans, its first span's color its dot's.
type Span = { text: string; color?: string; bold?: boolean; dimColor?: boolean }
// A desktop group is a drawing and the text beside it.
type Piece = { text: string; style?: { color?: string; bold?: boolean; dimColor?: boolean } }
type Group = {
  key: string
  color: string
  svg: { source: string; alt: string; width: number; height: number }
  pieces: Piece[]
}

// Held by the host, so they survive a hot reload of this file: one reading a turn, the
// quota windows, and the context fill as of the latest response.
const readings = atom({ plugin: 'token-weather', key: 'readings' } as const, [] as TokenWeatherReading[])
const limits = atom({ plugin: 'token-weather', key: 'limits' } as const, [] as TokenWeatherLimit[])
const live = atom({ plugin: 'token-weather', key: 'live' } as const, null as TokenWeatherReading | null)

export const register: Register = on => {
  let tick: Timer | undefined

  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await startReading($)
    tick?.cancel()
    tick = $.clock.every(TICK_MS, () => $.ui.invalidate('ui.render'))

    return result
  })

  // Every response of the turn, not just its end, moves the figures.
  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    await measure($, e.context, e.rateLimits)

    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    // Main-loop turns only, not subagents.
    if (e.agentId === undefined) {
      await takeReading($)
    }

    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const history = await read($, readings)
    const now = (await read($, live)) ?? history.at(-1)
    if (e.props.hasSurvey || !now) {
      return next(e)
    }

    const f = FORECAST.find(b => now.percent < b.upTo) ?? FORECAST[4]
    const quota = await read($, limits)
    const at = await $.clock.now()

    if (e.surface !== 'terminal') {
      const { Box, Text, Svg } = $.ui.resolve(e)
      const groups: Group[] = [
        {
          key: 'sky',
          color: f.color,
          svg: { source: glyph(f.sky, f.hex), alt: f.word, width: 16, height: 16 },
          pieces: [
            { text: f.word, style: { color: f.color, bold: true } },
            { text: `${now.percent}%` },
            { text: `${now.isEstimate ? '~' : ''}${short(now.tokens)} / ${short(now.window)}`, style: { dimColor: true } },
          ],
        },
        ...quota.map(l => quotaGroup(l, at)),
      ]
      const { bars, label } = turns(history, now)
      if (bars.length > 0) {
        const alt = bars.length === 1 ? 'Context added in the last turn' : `Context added in each of the last ${bars.length} turns`
        groups.push({
          key: 'trend',
          color: f.color,
          svg: { source: trend(bars, f.hex), alt, width: trendWidth(bars.length), height: 14 },
          pieces: [{ text: label, style: { dimColor: true } }],
        })
      }
      const k = fit(groups.map(g => iconCells(g) + 1 + textCells(g)), e.props.bodyColumns - 2)
      const hidden = groups.slice(k)

      return (
        <Box flexDirection="row" flexGrow={1} alignItems="center" justifyContent="space-between" paddingX={1} gap={2}>
          {groups.slice(0, k).map(g => (
            <Box key={g.key} flexDirection="row" alignItems="center" gap={1}>
              <Svg {...g.svg} />
              {g.pieces.map((p, i) => (
                <Text key={String(i)} {...p.style}>
                  {p.text}
                </Text>
              ))}
            </Box>
          ))}
          {hidden.length > 0 && (
            <Box key="dots" flexDirection="row">
              {hidden.map(g => (
                <Text key={g.key} color={g.color}>
                  {DOT}
                </Text>
              ))}
            </Box>
          )}
        </Box>
      )
    }

    const { Box, Text } = $.ui.resolve(e)
    const spans: Span[][] = [
      [
        { text: `${f.icon}  ${f.word}`, color: f.color, bold: true },
        { text: ` ${now.percent}%` },
        { text: ` ${now.isEstimate ? '~' : ''}${short(now.tokens)} / ${short(now.window)}`, dimColor: true },
      ],
      ...quota.map(l => {
        const label: Span = { text: `${LIMIT_LABELS[l.kind]} ${l.percentUsed}%`, color: limitColor(l.percentUsed) }

        return SHOW_RESET.has(l.kind) && l.resetsAt
          ? [label, { text: ` Resets ${countdown(l.resetsAt, at)}`, dimColor: true }]
          : [label]
      }),
    ]
    const { bars, label } = turns(history, now)
    if (bars.length > 0) {
      spans.push([
        { text: sparkline(bars), color: f.color },
        { text: ` ${label}`, dimColor: true },
      ])
    }
    const k = fit(
      spans.map(group => group.reduce((n, span) => n + [...span.text].length, 0)),
      e.props.bodyColumns - 2,
    )
    const shown = spans.slice(0, k)
    const hidden = spans.slice(k)

    return (
      <Box flexDirection="row" paddingX={1}>
        <Text wrap="truncate-end">
          {shown.flatMap((group, g) => [
            ...(g > 0 ? [<Text key={`gap-${g}`}>{GAP}</Text>] : []),
            ...group.map((span, i) => (
              <Text key={`${g}-${i}`} color={span.color} bold={span.bold} dimColor={span.dimColor}>
                {span.text}
              </Text>
            )),
          ])}
          {hidden.length > 0 && <Text key="gap-dots">{GAP}</Text>}
          {hidden.map((group, g) => (
            <Text key={`dot-${g}`} color={group[0]?.color}>
              {DOT}
            </Text>
          ))}
        </Text>
      </Box>
    )
  })
}

// At the start, or a reload: before the session's first response the context is
// estimated locally; the quota waits for that response.
async function startReading($: EngineInterface) {
  const { context, rateLimits } = await $.session.usage()
  const reading = (await measure($, context, rateLimits)) ?? (context?.window ? await estimate($, context.window) : null)
  if (reading?.isEstimate) await update($, live, () => reading)
  if (reading) await addReading($, reading)
}

// After a turn: the figures as it left them, and the turn's reading. A turn answered
// with no quota at all is an API-key session, which shows none.
async function takeReading($: EngineInterface) {
  const { context, rateLimits } = await $.session.usage()
  if (pickLimits(rateLimits).length === 0) await update($, limits, () => [])
  const reading = await measure($, context, rateLimits)
  if (reading) await addReading($, reading)
}

// Takes what a response reported: the quota and the context.
async function measure($: EngineInterface, context: SessionContextUsage | undefined, rateLimits: SessionRateLimit[] | undefined) {
  const shown = pickLimits(rateLimits)
  if (shown.length > 0) await update($, limits, () => shown)
  if (!context?.window || context.tokens === undefined) return null
  const reading: TokenWeatherReading = {
    tokens: context.tokens,
    window: context.window,
    percent: context.percent ?? Math.round((context.tokens / context.window) * 100),
  }
  await update($, live, () => reading)

  return reading
}

// The windows the band shows, as the API reported them.
function pickLimits(rateLimits: SessionRateLimit[] | undefined): TokenWeatherLimit[] {
  return Object.keys(LIMIT_LABELS).flatMap(kind => {
    const found = rateLimits?.find(l => l.kind === kind)

    return found ? [{ kind, percentUsed: Math.round(found.percentUsed), resetsAt: found.resetsAt }] : []
  })
}

// The context before any response, counted locally (free): system prompt, tools, memory.
async function estimate($: EngineInterface, window: number): Promise<TokenWeatherReading | null> {
  try {
    const tokens = (await $.session.usage({ breakdown: 'summary' })).context?.breakdown?.totalTokens
    if (!tokens) return null

    return { tokens, window, percent: Math.round((tokens / window) * 100), isEstimate: true }
  } catch {
    return null
  }
}

// One reading a turn; one the same as the last (a reload, a resume) is no turn of its own.
async function addReading($: EngineInterface, reading: TokenWeatherReading) {
  await update($, readings, history => {
    const last = history.at(-1)
    if (last && last.tokens === reading.tokens && last.window === reading.window) return history

    return [...history, reading].slice(-HISTORY)
  })
}

function quotaGroup(l: TokenWeatherLimit, at: number): Group {
  const color = limitHex(l.percentUsed)
  const label: Piece = { text: `${LIMIT_LABELS[l.kind]} ${l.percentUsed}%`, style: { color: limitColor(l.percentUsed) } }
  if (l.kind === 'five_hour') {
    const left = l.resetsAt ? countdown(l.resetsAt, at) : undefined
    const alt =
      `5-hour limit: ${l.percentUsed}% used` +
      (left === undefined ? '' : left === 'now' ? ', resets now' : `, resets in ${left}`)

    return {
      key: l.kind,
      color: label.style?.color ?? color,
      svg: { source: dial({ used: l.percentUsed, now: at, color }), alt, width: 20, height: 20 },
      pieces: left === undefined ? [label] : [label, { text: `Resets ${left}`, style: { dimColor: true } }],
    }
  }
  const alt =
    `Weekly limit: ${l.percentUsed}% used` +
    (l.resetsAt
      ? `, day ${Math.min(Math.floor(elapsed(l.resetsAt, 7 * DAY, at) * 7), 6) + 1} of 7, resets ${weekday(l.resetsAt)} ${clockTime(l.resetsAt)}`
      : '')

  return {
    key: l.kind,
    color: label.style?.color ?? color,
    svg: { source: week({ used: l.percentUsed, color }), alt, width: WEEK_WIDTH, height: WEEK_HEIGHT },
    pieces: [label],
  }
}

// How many groups, from the left, fit one line of `columns` cells: GAP between groups,
// and after the last a GAP and a dot for each group left out. Never fewer than one.
function fit(widths: number[], columns: number) {
  for (let k = widths.length; k > 1; k--) {
    const hidden = widths.length - k
    const cells =
      widths.slice(0, k).reduce((n, w) => n + w, 0) + GAP.length * (k - 1) + (hidden > 0 ? GAP.length + hidden : 0)
    if (cells <= columns) return k
  }

  return 1
}

function iconCells(g: Group) {
  return Math.ceil(g.svg.width / CELL_PX)
}

function textCells(g: Group) {
  return g.pieces.reduce((n, p) => n + p.text.length + 1, -1)
}

// Time left until an ISO timestamp: 2h 41m, 41m, <1m, or now once it has passed. Whole
// minutes are floored, as the app's usage panel counts them.
function countdown(iso: string, now: number) {
  const ms = Date.parse(iso) - now
  if (ms <= 0) return 'now'
  const minutes = Math.floor(ms / 60_000)
  if (minutes === 0) return '<1m'
  const h = Math.floor(minutes / 60)
  const m = minutes % 60
  if (h === 0) return `${m}m`

  return m === 0 ? `${h}h` : `${h}h ${m}m`
}

// An ISO timestamp as local HH:MM.
function clockTime(iso: string) {
  const d = new Date(iso)

  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

// An ISO timestamp's local weekday, as Tue.
function weekday(iso: string) {
  return WEEKDAYS[new Date(iso).getDay()]
}

// Green below 60%, orange below 90%, red from there. The theme has no orange name,
// so that one is a hex on every surface.
function limitColor(percentUsed: number) {
  if (percentUsed >= 90) return 'red'
  if (percentUsed >= 60) return ORANGE

  return 'green'
}

// limitColor's hues as the desktop draws them, for the drawings.
function limitHex(percentUsed: number) {
  if (percentUsed >= 90) return '#e5484d'
  if (percentUsed >= 60) return ORANGE

  return '#46a759'
}

// What each turn added to the context; a compaction counts as nothing added.
function gains(history: TokenWeatherReading[]) {
  return history.slice(1).map((r, i) => Math.max(r.tokens - (history[i]?.tokens ?? r.tokens), 0))
}

function sparkline(values: number[]) {
  const top = Math.max(...values, 1)

  return values.map(v => BARS[Math.floor((v / top) * (BARS.length - 1))]).join('')
}

// The bars and their label. While a turn runs (the latest response is past the last
// turn's reading) its gain so far is the newest bar: This turn; once it ends, Last turn.
function turns(history: TokenWeatherReading[], now: TokenWeatherReading) {
  const last = history.at(-1)
  if (last && now.tokens !== last.tokens) {
    const d = now.tokens - last.tokens

    return { bars: [...gains(history), Math.max(d, 0)].slice(1 - HISTORY), label: `This turn ${arrow(d)}` }
  }
  const d = (history.at(-1)?.tokens ?? 0) - (history.at(-2)?.tokens ?? 0)

  return { bars: gains(history), label: `Last turn ${arrow(d)}` }
}

function arrow(d: number) {
  if (d === 0) return '0'

  return d > 0 ? `↑${short(d)}` : `↓${short(-d)}`
}

function short(n: number) {
  if (n >= 1_000_000) return `${+(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${+(n / 1_000).toFixed(1)}k`

  return String(n)
}

