// The drawings the surfaces with Svg show: plain SVG markup built from the band's figures.

export type Sky = 'sun' | 'cloud' | 'rain' | 'storm' | 'funnel'

export const HOUR = 3_600_000
export const DAY = 24 * HOUR
export const WEEK_WIDTH = 54
export const WEEK_HEIGHT = 9

// Mid-tones that read on the desktop's dark card and on a light one.
const TRACK = 'rgba(137,135,129,0.3)'
const PAST = 'rgba(137,135,129,0.6)'
const MARK = '#898781'
// Deeper takes on the band's hues, for a light card where the scheme says so.
const ON_LIGHT: Record<string, string> = {
  '#f6d909': '#b39b00',
  '#46a759': '#2f8a43',
  '#e5484d': '#c9372f',
  '#f0883e': '#c4661a',
  '#08a2c3': '#06819b',
  '#5b8def': '#3a6fd8',
  '#b77ce0': '#9150c4',
}

const CLOUD = 'M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9z'
const RAISED = `<path d="${CLOUD}" transform="translate(0 -3)"/>`
const SKY: Record<Sky, string> = {
  sun:
    '<circle cx="12" cy="12" r="4"/>' +
    [0, 45, 90, 135, 180, 225, 270, 315].map(a => `<path d="M${at(a, 7.5)}L${at(a, 10)}"/>`).join(''),
  cloud: `<path d="${CLOUD}"/>`,
  rain: `${RAISED}<path d="M8 18.5l-1 3M12 18.5l-1 3M16 18.5l-1 3"/>`,
  storm: `${RAISED}<path d="M13 16.5l-2.5 3.5h3.5l-2.5 3.5"/>`,
  funnel: '<path d="M3 5h18M5 9h13M8 13h9M10 17h5M12 21h1.5"/>',
}

// The weather icon, stroked in the forecast's color.
export function glyph(sky: Sky, color: string) {
  return svg(
    24,
    24,
    `class="k" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"`,
    light(color, 'stroke') + SKY[sky],
  )
}

// A small clock: the rim fills clockwise from twelve as the quota is used, and the
// two hands show the time and keep turning.
export function dial(o: { used: number; now: number; color: string }) {
  const minute = (new Date(o.now).getMinutes() + new Date(o.now).getSeconds() / 60) * 6

  return svg(
    24,
    24,
    'fill="none" stroke-linecap="round"',
    light(o.color, 'stroke') +
      `<circle cx="12" cy="12" r="10" stroke="${TRACK}" stroke-width="2.5"/>` +
      rim(share(o.used) * 359.99, o.color) +
      hand(face(o.now), 4.5, 43_200) +
      hand(minute, 6.5, 3_600),
  )
}

// Seven day cells filled as far as the quota is used.
export function week(o: { used: number; color: string }) {
  const filled = share(o.used) * 7
  let cells = ''
  for (let i = 0; i < 7; i++) {
    const x = i * 8
    const part = Math.min(Math.max(filled - i, 0), 1)
    cells += `<rect x="${x}" y="0" width="6" height="9" rx="2" fill="${TRACK}"/>`
    if (part > 0) {
      cells += `<rect class="k" x="${x}" y="0" width="${+(6 * part).toFixed(2)}" height="9" rx="2" fill="${o.color}"/>`
    }
  }

  return svg(WEEK_WIDTH, WEEK_HEIGHT, '', light(o.color, 'fill') + cells)
}

// What each of the last turns added to the context, as bars; the newest in the forecast's color.
export function trend(values: number[], color: string) {
  const top = Math.max(...values, 1)
  const bars = values
    .map((v, i) => {
      const h = Math.max((v / top) * 14, 1.5)
      const paint = i === values.length - 1 ? `class="k" fill="${color}"` : `fill="${PAST}"`

      return `<rect x="${i * 5}" y="${+(14 - h).toFixed(2)}" width="3" height="${+h.toFixed(2)}" rx="1" ${paint}/>`
    })
    .join('')

  return svg(trendWidth(values.length), 14, '', light(color, 'fill') + bars)
}

export function trendWidth(count: number) {
  return Math.max(count * 5 - 2, 1)
}

// How much of a window ending at `resetsAt` has passed at `now`, 0 to 1.
export function elapsed(resetsAt: string, span: number, now: number) {
  return Math.min(Math.max((now - (Date.parse(resetsAt) - span)) / span, 0), 1)
}

// Repaints the `k` marks in the deeper hue when the scheme is light.
function light(color: string, prop: 'fill' | 'stroke') {
  const deeper = ON_LIGHT[color]

  return deeper ? `<style>@media (prefers-color-scheme: light){.k{${prop}:${deeper}}}</style>` : ''
}

function share(percent: number) {
  return Math.min(Math.max(percent, 0), 100) / 100
}

// Degrees on a 12-hour face, clockwise from twelve, for a moment in local time.
function face(ms: number) {
  const d = new Date(ms)

  return ((d.getHours() % 12) * 60 + d.getMinutes() + d.getSeconds() / 60) / 2
}

function at(deg: number, r: number) {
  const a = (deg * Math.PI) / 180

  return `${+(12 + r * Math.sin(a)).toFixed(2)} ${+(12 - r * Math.cos(a)).toFixed(2)}`
}

// The colored part of the rim, clockwise from twelve.
function rim(sweep: number, color: string) {
  if (sweep <= 0) return ''

  return `<path class="k" d="M${at(0, 10)}A10 10 0 ${sweep > 180 ? 1 : 0} 1 ${at(sweep, 10)}" stroke="${color}" stroke-width="2.5"/>`
}

// A hand at `deg` that goes once round the face every `period` seconds.
function hand(deg: number, length: number, period: number) {
  return (
    `<g transform="rotate(${deg} 12 12)"><path d="M12 12V${12 - length}" stroke="${MARK}" stroke-width="1.8"/>` +
    `<animateTransform attributeName="transform" type="rotate" from="${deg} 12 12" to="${deg + 360} 12 12" dur="${period}s" repeatCount="indefinite"/></g>`
  )
}

function svg(w: number, h: number, attrs: string, body: string) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" ${attrs}>${body}</svg>`
}

