// `isEstimate`: counted locally before the session's first response, not reported by the API.
export type TokenWeatherReading = { tokens: number; window: number; percent: number; isEstimate?: boolean }
export type TokenWeatherLimit = { kind: string; percentUsed: number; resetsAt?: string }

declare module 'claude-code' {
  interface PluginState {
    'token-weather': { readings: TokenWeatherReading[]; limits: TokenWeatherLimit[]; live: TokenWeatherReading | null }
  }
}
